\n    }\n  }\n\n  function createChart() {\n    if (!canvasRef.value) return\n\n    chart?.destroy()\n    chart = new Chart(canvasRef.value, {\n      type: type.value,\n      data: copyData(),\n      options: getDefaultOptions(type.value)\n    })\n  }\n\n  onMounted(createChart)\n\n  watch(type, createChart)\n\n  watch(\n    data,\n    () => {\n      if (!chart) return\n      const next = copyData()\n      const previousCount = chart.data.datasets.length\n      for (const [index, dataset] of next.datasets.entries()) {\n        if (index >= previousCount) break\n        const { hidden } = chart.getDatasetMeta(index)\n        if (typeof hidden === 'boolean') dataset.hidden = hidden\n      }\n      chart.data = next\n      chart.update()\n    },\n    { deep: true }\n  )\n\n  onBeforeUnmount(() => {\n    chart?.destroy()\n    chart = undefined\n  })\n}\n","<template>\n  <div :class=\"cn('rounded-lg bg-secondary-background p-6', className)\">\n    <div class=\"relative\">\n      <canvas ref=\"canvasRef\" :aria-label=\"label\" role=\"img\" />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { ChartData } from 'chart.js'\nimport { toRef, useTemplateRef } from 'vue'\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { useChart } from './useChart'\nimport type { SupportedChartType } from './useChart'\n\nconst {\n  data,\n  label,\n  type,\n  class: className\n} = defineProps<{\n  data: ChartData\n  label: string\n  type: SupportedChartType\n  class?: HTMLAttributes['class']\n}>()\n\nconst canvasRef = useTemplateRef<HTMLCanvasElement>('canvasRef')\n\nuseChart(\n  canvasRef,\n  toRef(() => type),\n  toRef(() => data)\n)\n</script>\n","<template>\n  <div :class=\"cn('rounded-lg bg-secondary-background p-6', className)\">\n    <div class=\"relative\">\n      <canvas ref=\"canvasRef\" :aria-label=\"label\" role=\"img\" />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { 